@dataclass(frozen=True)
class ContextWindow:
    """One immutable, exactly encoded request prepared for generation."""

    messages: tuple[Message, ...]
    token_ids: tuple[int, ...]
    visible_tool_result_bytes: int
    followed_compaction: bool
    compaction_event_id: str | None


class ContextLimitError(AgentError):
    """The required anchors and recent complete turns cannot fit safely."""


def compact_messages(messages: list[Message], max_chars: int) -> list[Message]:
    """Retain anchors, standalone messages, and complete recent tool turns."""

    if max_chars <= 0:
        raise ValueError("max_chars must be positive")
    total_chars = sum(len(item["content"]) for item in messages)
    if len(messages) <= 2 or total_chars <= max_chars:
        return list(messages)

    anchors = list(messages[:2])
    anchor_chars = sum(len(item["content"]) for item in anchors)
    turns: list[list[Message]] = []
    index = 2
    while index < len(messages):
        message = messages[index]
        if (
            message["role"] == "assistant"
            and index + 1 < len(messages)
            and messages[index + 1]["role"] == "user"
            and messages[index + 1]["content"].startswith("Tool result:\n")
        ):
            turns.append(messages[index : index + 2])
            index += 2
        else:
            turns.append([message])
            index += 1
    kept: list[list[Message]] = []
    used = anchor_chars
    for turn in reversed(turns):
        turn_chars = sum(len(item["content"]) for item in turn)
        if used + turn_chars > max_chars:
            if not kept:
                kept.append(turn)
            break
        kept.append(turn)
        used += turn_chars
    return anchors + [item for turn in reversed(kept) for item in turn]


def append_tool_result(
    messages: list[Message], response: str, result: str
) -> list[Message]:
    """Record an action and its observation as one complete semantic turn."""

    return messages + [
        {"role": "assistant", "content": response},
        {"role": "user", "content": f"Tool result:\n{result}"},
    ]


class ContextManager:
    """Build bounded semantic context without modifying canonical events."""

    def __init__(
        self,
        encode_messages: Callable[[list[Message]], Iterable[int]],
        policy: ContextPolicy | None = None,
    ):
        self._encode_messages = encode_messages
        self.policy = policy or ContextPolicy()

    def _encode(self, messages: list[Message]) -> tuple[int, ...]:
        tokens = tuple(self._encode_messages(messages))
        if any(
            isinstance(token, bool) or not isinstance(token, int) for token in tokens
        ):
            raise ValueError("message encoder must return integer token IDs")
        return tokens

    @staticmethod
    def _bounded_text(value: str, limit: int = _MAX_ATTEMPT_TEXT) -> str:
        encoded = value.encode("utf-8")
        if len(encoded) <= limit:
            return value
        suffix = "... omitted"
        available = max(0, limit - len(suffix.encode("utf-8")))
        return encoded[:available].decode("utf-8", errors="ignore") + suffix

    def _tool_payload_tokens(self, content: str) -> int:
        return len(self._encode([{"role": "user", "content": content}]))

    def _bound_tool_result(self, content: str, tool: str | None) -> str:
        if self._tool_payload_tokens(content) <= self.policy.max_tool_result_tokens:
            return content
        marker = "\n[... tool output omitted ...]\n"
        low = 0
        high = len(content)
        best = marker.strip()
        while low <= high:
            kept = (low + high) // 2
            if tool == "list_files":
                candidate = content[:kept] + marker
            elif tool == "run_command":
                candidate = marker + (content[-kept:] if kept else "")
            else:
                head_length = (kept + 1) // 2
                tail_length = kept // 2
                candidate = content[:head_length] + marker
                if tail_length:
                    candidate += content[-tail_length:]
            if (
                self._tool_payload_tokens(candidate)
                <= self.policy.max_tool_result_tokens
            ):
                best = candidate
                low = kept + 1
            else:
                high = kept - 1
        if self._tool_payload_tokens(best) <= self.policy.max_tool_result_tokens:
            return best
        raise ContextLimitError(
            "tool-result omission marker exceeds max_tool_result_tokens"
        )

    @staticmethod
    def _complete_boundaries(events: tuple[SessionEvent, ...]) -> tuple[int, ...]:
        """Return one explicit closure boundary for each semantic model turn."""

        result_indexes = {
            event.data.get("tool_call_id"): index
            for index, event in enumerate(events)
            if event.type == "tool_result"
        }
        protocol_types = {
            "assistant_message",
            "run_finished",
            "tool_call",
            "tool_result",
            "user_message",
        }
        boundaries: list[int] = []
        for assistant_index, event in enumerate(events):
            if event.type != "assistant_message":
                continue
            following = next(
                (
                    (index, candidate)
                    for index, candidate in enumerate(
                        events[assistant_index + 1 :], start=assistant_index + 1
                    )
                    if candidate.type in protocol_types
                ),
                None,
            )
            if following is None:
                continue
            following_index, following_event = following
            if following_event.type == "tool_call":
                result_index = result_indexes.get(following_event.id)
                if result_index is not None:
                    boundaries.append(result_index)
            elif following_event.type == "tool_result":
                boundaries.append(following_index)
            elif following_event.type == "run_finished":
                boundaries.append(following_index)
            elif following_event.type in {"assistant_message", "user_message"}:
                boundaries.append(assistant_index)
        return tuple(sorted(set(boundaries)))

    @staticmethod
    def _validated_latest_compaction(
        events: tuple[SessionEvent, ...],
    ) -> tuple[SessionEvent | None, int]:
        indexes = {event.id: index for index, event in enumerate(events)}
        result_indexes = {
            event.data.get("tool_call_id"): index
            for index, event in enumerate(events)
            if event.type == "tool_result"
        }
        latest = None
        previous_boundary = -1
        complete_boundaries = set(ContextManager._complete_boundaries(events))
        for marker_index, event in enumerate(events):
            if event.type != "compaction":
                continue
            if set(event.data) != {
                "covered_through_event_id",
                "strategy",
                "fallback_reason",
                "summary",
                "input_tokens_before",
                "input_tokens_after",
            }:
                raise ContextLimitError("compaction event fields are invalid")
            try:
                ContextManager._parse_summary(
                    json.dumps(event.data.get("summary"), ensure_ascii=False)
                )
            except ValueError as error:
                raise ContextLimitError("compaction summary is invalid") from error
            covered_id = event.data.get("covered_through_event_id")
            if not isinstance(covered_id, str) or covered_id not in indexes:
                raise ContextLimitError("compaction references a missing session event")
            boundary = indexes[covered_id]
            if boundary <= previous_boundary or boundary >= marker_index:
                raise ContextLimitError("compaction boundaries are not monotonic")
            if boundary not in complete_boundaries:
                raise ContextLimitError("compaction boundary is not a complete turn")
            strategy = event.data.get("strategy")
            reason = event.data.get("fallback_reason")
            before = event.data.get("input_tokens_before")
            after = event.data.get("input_tokens_after")
            if strategy not in {"model", "deterministic"}:
                raise ContextLimitError("compaction strategy is invalid")
            if strategy == "model" and reason is not None:
                raise ContextLimitError("model compaction has a fallback reason")
            if strategy == "deterministic" and (
                not isinstance(reason, str) or not reason or len(reason) > 1_024
            ):
                raise ContextLimitError("deterministic compaction reason is invalid")
            if (
                isinstance(before, bool)
                or not isinstance(before, int)
                or isinstance(after, bool)
                or not isinstance(after, int)
                or after < 0
                or before <= after
            ):
                raise ContextLimitError("compaction token counts are invalid")
            for call_index, call in enumerate(events[: boundary + 1]):
                if call.type != "tool_call":
                    continue
                result_index = result_indexes.get(call.id)
                if result_index is None or result_index > boundary:
                    raise ContextLimitError("compaction crosses an unmatched tool call")
            previous_boundary = boundary
            latest = event
        return latest, previous_boundary

    @staticmethod
    def _summary_dict(value: WorkingSummary) -> dict[str, Any]:
        return {
            "goal": value.goal,
            "constraints": list(value.constraints),
            "facts": list(value.facts),
            "changed_files": list(value.changed_files),
            "validation": list(value.validation),
            "failed_approaches": list(value.failed_approaches),
            "next_step": value.next_step,
        }

    @classmethod
    def _parse_summary(cls, raw: str) -> WorkingSummary:
        try:
            value = json.loads(raw)
        except (json.JSONDecodeError, TypeError) as error:
            raise ValueError("summary response is not valid JSON") from error
        if not isinstance(value, dict) or tuple(value) != _SUMMARY_FIELDS:
            # Accept a different JSON key order, but never missing or extra keys.
            if not isinstance(value, dict) or set(value) != set(_SUMMARY_FIELDS):
                raise ValueError("summary fields do not match the schema")
        goal = value["goal"]
        next_step = value["next_step"]
        if (
            not isinstance(goal, str)
            or not goal.strip()
            or len(goal) > _MAX_SUMMARY_TEXT
            or not isinstance(next_step, str)
            or not next_step.strip()
            or len(next_step) > _MAX_SUMMARY_TEXT
        ):
            raise ValueError("summary goal and next_step must be bounded strings")
        lists: dict[str, tuple[str, ...]] = {}
        for field in _SUMMARY_LIST_FIELDS:
            items = value[field]
            if (
                not isinstance(items, list)
                or len(items) > _MAX_SUMMARY_ITEMS
                or any(
                    not isinstance(item, str)
                    or not item.strip()
                    or len(item) > _MAX_SUMMARY_TEXT
                    for item in items
                )
            ):
                raise ValueError(f"summary {field} must be a bounded string array")
            lists[field] = tuple(items)
        return WorkingSummary(
            goal=goal,
            constraints=lists["constraints"],
            facts=lists["facts"],
            changed_files=lists["changed_files"],
            validation=lists["validation"],
            failed_approaches=lists["failed_approaches"],
            next_step=next_step,
        )

    @staticmethod
    def _summary_message(summary: WorkingSummary) -> Message:
        payload = ContextManager._summary_dict(summary)
        return {
            "role": "user",
            "content": "Working summary:\n"
            + json.dumps(payload, ensure_ascii=False, sort_keys=True),
        }

    @staticmethod
    def _prior_summary(event: SessionEvent | None) -> WorkingSummary | None:
        if event is None:
            return None
        try:
            return ContextManager._parse_summary(
                json.dumps(event.data.get("summary"), ensure_ascii=False)
            )
        except ValueError as error:
            raise ContextLimitError("durable compaction summary is invalid") from error

    def _validate_compaction_provenance(self, events: tuple[SessionEvent, ...]) -> None:
        """Recompute protected facts from original structured events on replay."""

        indexes = {event.id: index for index, event in enumerate(events)}
        for event in events:
            if event.type != "compaction":
                continue
            summary = self._prior_summary(event)
            assert summary is not None
            boundary = indexes[event.data["covered_through_event_id"]]
            structured = self._deterministic_summary(events, -1, boundary, None)
            if (
                summary.changed_files != structured.changed_files
                or summary.validation != structured.validation
            ):
                raise ContextLimitError(
                    "compaction protected facts do not match structured events"
                )

    @staticmethod
    def _first_task(events: tuple[SessionEvent, ...]) -> SessionEvent | None:
        return next(
            (
                event
                for event in events
                if event.type == "user_message"
                and isinstance(event.data.get("content"), str)
            ),
            None,
        )

    def _system_message(self, session: SessionLog, system_prompt: str) -> Message:
        return dict(session.messages(system_prompt)[0])

    def _messages_after(
        self,
        events: tuple[SessionEvent, ...],
        start_index: int,
        *,
        end_index: int | None = None,
        skip_event_ids: set[str] | None = None,
    ) -> tuple[list[Message], int]:
        messages: list[Message] = []
        visible_bytes = 0
        skipped = skip_event_ids or set()
        stop = len(events) if end_index is None else end_index + 1
        for event in events[start_index + 1 : stop]:
            if event.id in skipped:
                continue
            content = event.data.get("content")
            if event.type == "user_message" and isinstance(content, str):
                messages.append({"role": "user", "content": content})
            elif event.type == "assistant_message" and isinstance(content, str):
                messages.append({"role": "assistant", "content": content})
            elif event.type == "tool_result" and isinstance(content, str):
                tool = event.data.get("tool")
                visible = self._bound_tool_result(
                    content, tool if isinstance(tool, str) else None
                )
                visible_bytes += len(visible.encode("utf-8"))
                messages.append({"role": "user", "content": f"Tool result:\n{visible}"})
        return messages, visible_bytes

    def _build_messages(
        self,
        session: SessionLog,
        system_prompt: str,
        events: tuple[SessionEvent, ...],
        covered_index: int,
        summary: WorkingSummary | None,
    ) -> tuple[list[Message], int]:
        messages = [self._system_message(session, system_prompt)]
        task = self._first_task(events)
        skipped: set[str] = set()
        if task is not None:
            messages.append({"role": "user", "content": task.data["content"]})
            skipped.add(task.id)
        if summary is not None:
            messages.append(self._summary_message(summary))
        current_request = next(
            (
                (index, event)
                for index, event in reversed(tuple(enumerate(events)))
                if event.type == "user_message"
                and isinstance(event.data.get("content"), str)
            ),
            None,
        )
        if (
            current_request is not None
            and current_request[1].id not in skipped
            and current_request[0] <= covered_index
        ):
            messages.append(
                {
                    "role": "user",
                    "content": current_request[1].data["content"],
                }
            )
            skipped.add(current_request[1].id)
        tail, visible_bytes = self._messages_after(
            events, covered_index, skip_event_ids=skipped
        )
        messages.extend(tail)
        return messages, visible_bytes

    def _anchor_messages(
        self, session: SessionLog, system_prompt: str, events: tuple[SessionEvent, ...]
    ) -> list[Message]:
        messages = [self._system_message(session, system_prompt)]
        user_events = [
            event
            for event in events
            if event.type == "user_message"
            and isinstance(event.data.get("content"), str)
        ]
        if user_events:
            messages.append({"role": "user", "content": user_events[0].data["content"]})
        if len(user_events) > 1:
            messages.append(
                {"role": "user", "content": user_events[-1].data["content"]}
            )
        return messages

    @staticmethod
    def _coverage_boundary(
        events: tuple[SessionEvent, ...],
        covered_index: int,
        min_recent_turns: int,
    ) -> int | None:
        matched_call_ids = {
            event.data.get("tool_call_id")
            for event in events
            if event.type == "tool_result"
        }
        unmatched_indexes = [
            index
            for index, event in enumerate(events)
            if event.type == "tool_call" and event.id not in matched_call_ids
        ]
        ceiling = min(unmatched_indexes, default=len(events))
        completions = [
            index
            for index in ContextManager._complete_boundaries(events)
            if covered_index < index < ceiling
        ]
        if len(completions) <= min_recent_turns:
            return None
        return (
            completions[-min_recent_turns - 1] if min_recent_turns else completions[-1]
        )

    @staticmethod
    def _unique_bounded(values: Iterable[str]) -> tuple[str, ...]:
        result: list[str] = []
        for value in values:
            value = value.strip()[:_MAX_SUMMARY_TEXT]
            if value and value not in result:
                result.append(value)
            if len(result) >= _MAX_SUMMARY_ITEMS:
                break
        return tuple(result)

    def _deterministic_summary(
        self,
        events: tuple[SessionEvent, ...],
        covered_index: int,
        boundary: int,
        prior: WorkingSummary | None,
    ) -> WorkingSummary:
        task = self._first_task(events)
        goal = (
            prior.goal
            if prior is not None
            else str(task.data.get("content", "Continue the coding task"))
            if task is not None
            else "Continue the coding task"
        )
        constraints = list(prior.constraints if prior is not None else ())
        facts = list(prior.facts if prior is not None else ())
        changed_files = list(prior.changed_files if prior is not None else ())
        validation = list(prior.validation if prior is not None else ())
        failed = list(prior.failed_approaches if prior is not None else ())
        calls: dict[str, SessionEvent] = {}
        for event in events[covered_index + 1 : boundary + 1]:
            if event.type == "tool_call":
                calls[event.id] = event
            elif event.type == "tool_result":
                content = event.data.get("content")
                call = calls.get(str(event.data.get("tool_call_id")))
                tool = (
                    call.data.get("tool")
                    if call is not None
                    else event.data.get("tool")
                )
                if isinstance(content, str):
                    bounded = self._bounded_text(content, _MAX_SUMMARY_TEXT)
                    if event.data.get("is_error") or content.startswith("error:"):
                        failed.append(f"{tool or 'tool'}: {bounded}")
                    else:
                        if isinstance(tool, str):
                            facts.append(f"Completed tool call: {tool}")
                        if call is not None and tool in {"write_file", "edit_file"}:
                            arguments = call.data.get("arguments")
                            if isinstance(arguments, dict):
                                path = arguments.get("path")
                                if isinstance(path, str):
                                    changed_files.append(path)
                        if tool == "run_command":
                            status = content.splitlines()[0] if content else ""
                            if status.startswith("exit code:"):
                                validation.append(status)
        return WorkingSummary(
            goal=goal.strip()[:_MAX_SUMMARY_TEXT] or "Continue the coding task",
            constraints=self._unique_bounded(constraints),
            facts=self._unique_bounded(facts),
            changed_files=self._unique_bounded(changed_files),
            validation=self._unique_bounded(validation),
            failed_approaches=self._unique_bounded(failed),
            next_step="Continue from the newest preserved complete turn.",
        )

    @staticmethod
    def _reconcile_model_summary(
        model_summary: WorkingSummary, structured: WorkingSummary
    ) -> WorkingSummary:
        """Keep model prose while deriving mutation and validation facts from events."""

        return WorkingSummary(
            goal=model_summary.goal,
            constraints=model_summary.constraints,
            facts=model_summary.facts,
            changed_files=structured.changed_files,
            validation=structured.validation,
            failed_approaches=model_summary.failed_approaches,
            next_step=model_summary.next_step,
        )

    @staticmethod
    def _summary_request(source_messages: list[Message]) -> list[Message]:
        schema = {
            field: (["string"] if field in _SUMMARY_LIST_FIELDS else "string")
            for field in _SUMMARY_FIELDS
        }
        return [
            {
                "role": "system",
                "content": (
                    "Summarize the coding-agent transcript. Return only one JSON "
                    "object with exactly this schema: "
                    + json.dumps(schema, sort_keys=True)
                ),
            },
            *source_messages[1:],
            {
                "role": "user",
                "content": "Return the bounded working summary JSON now.",
            },
        ]

    def _summary_fits(self, summary: WorkingSummary) -> bool:
        return (
            len(self._encode([self._summary_message(summary)]))
            <= self.policy.summary_max_tokens
        )

    def _shrink_summary(self, summary: WorkingSummary) -> WorkingSummary:
        current = summary
        if self._summary_fits(current):
            return current
        removable_fields = ("constraints", "facts", "failed_approaches")
        fields = {field: list(getattr(current, field)) for field in removable_fields}
        while any(fields.values()):
            longest = max(fields, key=lambda field: len(fields[field]))
            fields[longest].pop()
            current = WorkingSummary(
                goal=summary.goal,
                constraints=tuple(fields["constraints"]),
                facts=tuple(fields["facts"]),
                changed_files=summary.changed_files,
                validation=summary.validation,
                failed_approaches=tuple(fields["failed_approaches"]),
                next_step=summary.next_step,
            )
            if self._summary_fits(current):
                return current
        return current

    def prepare(
        self,
        session: SessionLog,
        system_prompt: str,
        summarize: Callable[[list[Message]], str] | None = None,
    ) -> ContextWindow:
        """Prepare one bounded request and durably record any new compaction."""

        events = session.events
        anchor_tokens = self._encode(
            self._anchor_messages(session, system_prompt, events)
        )
        if len(anchor_tokens) > self.policy.working_tokens:
            raise ContextLimitError("required context anchors exceed the token budget")

        prior_event, covered_index = self._validated_latest_compaction(events)
        self._validate_compaction_provenance(events)
        prior_summary = self._prior_summary(prior_event)
        messages, visible_bytes = self._build_messages(
            session, system_prompt, events, covered_index, prior_summary
        )
        tokens_before = self._encode(messages)
        if len(tokens_before) <= self.policy.working_tokens:
            return ContextWindow(
                tuple(messages), tokens_before, visible_bytes, False, None
            )

        boundary = self._coverage_boundary(
            events, covered_index, self.policy.min_recent_turns
        )
        if boundary is None or boundary <= covered_index:
            raise ContextLimitError("minimum safe context exceeds the token budget")

        fallback_reason: str | None = None
        strategy = "deterministic"
        summary_value: WorkingSummary | None = None
        structured_summary = self._shrink_summary(
            self._deterministic_summary(events, covered_index, boundary, prior_summary)
        )
        if summarize is not None:
            source_messages, _ = self._build_messages(
                session,
                system_prompt,
                events[: boundary + 1],
                covered_index,
                prior_summary,
            )
            summary_messages = self._summary_request(source_messages)
            raw_response: str | None = None
            attempt_error: str | None = None
            status = "accepted"
            if (
                len(self._encode(summary_messages)) + self.policy.summary_max_tokens
                > self.policy.max_tokens
            ):
                status = "invalid"
                attempt_error = "summary input plus output reserve exceeds max_tokens"
            else:
                try:
                    raw = summarize(summary_messages)
                    if not isinstance(raw, str):
                        raise ValueError("summary response must be a string")
                    raw_response = self._bounded_text(raw)
                    if raw_response != raw:
                        raise ValueError("summary response exceeds the audit bound")
                    parsed = self._parse_summary(raw)
                    summary_value = self._reconcile_model_summary(
                        parsed, structured_summary
                    )
                    if not self._summary_fits(summary_value):
                        raise ValueError("summary exceeds summary_max_tokens")
                except AgentInterrupted:
                    raise
                except ValueError as error:
                    status = "invalid"
                    attempt_error = self._bounded_text(str(error), 1_024)
                    summary_value = None
                except Exception as error:
                    status = "error"
                    attempt_error = self._bounded_text(str(error), 1_024)
                    summary_value = None
            session.append(
                "summary_attempt",
                status=status,
                response=raw_response,
                error=attempt_error,
            )
            if summary_value is not None:
                strategy = "model"
            else:
                fallback_reason = attempt_error or "invalid summary response"
        else:
            fallback_reason = "no summarizer provided"

        if summary_value is None:
            summary_value = structured_summary
        if not self._summary_fits(summary_value):
            raise ContextLimitError("minimum structured summary exceeds its budget")

        candidate, candidate_visible_bytes = self._build_messages(
            session, system_prompt, events, boundary, summary_value
        )
        candidate_tokens = self._encode(candidate)
        if len(candidate_tokens) > self.policy.working_tokens and strategy == "model":
            strategy = "deterministic"
            fallback_reason = "model summary did not leave enough working context"
            summary_value = structured_summary
            candidate, candidate_visible_bytes = self._build_messages(
                session, system_prompt, events, boundary, summary_value
            )
            candidate_tokens = self._encode(candidate)
        if len(candidate_tokens) > self.policy.working_tokens:
            raise ContextLimitError("minimum safe context exceeds the token budget")

        event = session.append(
            "compaction",
            covered_through_event_id=events[boundary].id,
            strategy=strategy,
            fallback_reason=fallback_reason,
            summary=self._summary_dict(summary_value),
            input_tokens_before=len(tokens_before),
            input_tokens_after=len(candidate_tokens),
        )
        return ContextWindow(
            tuple(candidate),
            candidate_tokens,
            candidate_visible_bytes,
            True,
            event.id,
        )
